using System;
using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonObjectiveStartSetup
    {
        static T Copy<T>(T source,Transform root,Transform target) where T:Component{return target.Find(AnimationUtility.CalculateTransformPath(source.transform,root)).GetComponent<T>();}
        static void Place(RectTransform r,float x,float y,float w,float h){r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);}
        static void Bind(Button b,UnityEngine.Events.UnityAction action){b.onClick=new Button.ButtonClickedEvent();UnityEventTools.AddPersistentListener(b.onClick,action);b.onClick.SetPersistentListenerState(0,UnityEngine.Events.UnityEventCallState.EditorAndRuntime);}
        static Button Button(Transform parent,string name,string caption,float x){var go=DefaultControls.CreateButton(new DefaultControls.Resources());go.name=name;go.transform.SetParent(parent,false);Place(go.GetComponent<RectTransform>(),x,78,211,40);var text=go.GetComponentInChildren<Text>();text.font=ContentPreviewLayout.LoadFont();text.fontSize=16;text.text=caption;return go.GetComponent<Button>();}
        [MenuItem("Cat Cafe/開発用/UI再生成/経営目標の開始",false,38)]
        public static void Build()
        {
            var scene=EditorSceneManager.OpenScene("Assets/Scenes/CatCafePythonState.unity");var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();var source=preview.GetComponent<PythonDayOffPanel>();var root=source.panel.transform.parent;var old=root.Find("Objective Start");if(old!=null)UnityEngine.Object.DestroyImmediate(old.gameObject);
            var p=preview.GetComponent<PythonObjectiveStartPanel>() ?? preview.gameObject.AddComponent<PythonObjectiveStartPanel>();p.panel=UnityEngine.Object.Instantiate(source.panel,root);p.panel.name="Objective Start";var s=source.panel.transform;var t=p.panel.transform;
            p.title=Copy(source.title,s,t);p.details=Copy(source.details,s,t);p.notice=Copy(source.notice,s,t);p.proceed=Copy(source.proceed,s,t);p.close=Copy(source.close,s,t);p.confirm=Copy(source.confirm,s,t);p.cancel=Copy(source.cancel,s,t);p.confirmation=t.Find(AnimationUtility.CalculateTransformPath(source.confirmation.transform,s)).gameObject;var card=p.close.transform.parent;
            p.tabs=new[]{Button(card,"Popularity","人気への挑戦",24),Button(card,"Bond","猫との好感度",251),Button(card,"Patron","有力者の満足度",478),Button(card,"Management","旧営業の経営ルール",705)};Bind(p.tabs[0],p.Popularity);Bind(p.tabs[1],p.Bond);Bind(p.tabs[2],p.Patron);Bind(p.tabs[3],p.Management);
            var scroll=p.details.transform.parent.parent.GetComponent<ScrollRect>();Place(scroll.GetComponent<RectTransform>(),24,130,892,352);Place(scroll.viewport,6,6,862,340);scroll.verticalScrollbar.GetComponent<RectTransform>().sizeDelta=new Vector2(12,340);p.details.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal,862);p.details.fontSize=18;
            UnityEngine.Object.DestroyImmediate(Copy(source.confirmationText,s,t).gameObject);var confirmArea=UnityEngine.Object.Instantiate(scroll.gameObject,p.confirmation.transform);confirmArea.name="Conditions Scroll";var confirmScroll=confirmArea.GetComponent<ScrollRect>();Place(confirmArea.GetComponent<RectTransform>(),24,64,892,360);p.confirmationText=confirmScroll.content.GetComponent<Text>();
            Bind(p.proceed,p.Choose);Bind(p.close,p.Close);Bind(p.confirm,p.Confirm);Bind(p.cancel,p.Cancel);p.proceed.GetComponentInChildren<Text>().text="この目標を開始（確認）";p.notice.fontSize=14;p.confirmation.SetActive(false);p.panel.SetActive(false);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);PythonEventListSetup.Build();Debug.Log("CAT_CAFE_OBJECTIVE_START_UI_OK");
        }
        public static void BuildAndVerify()
        {
            Build();var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",f).SetValue(client,preview);
            var state=PythonServiceSetup.Sample();state.instance_id="objective-start";state.can_set_shifts=true;state.required_action="";state.objective_start=new PythonObjectiveStart{notes="営業準備中に一度だけ開始できます。開始時のモードは変更しません。",rows=new[]{new PythonStartObjective{choice="popularity",label="人気への挑戦",can_start=true,details="人気250（20日間） → 人気450（20日間） → 人気650（25日間）\n開始日を含む期限です。休業も日数に含みます。\n現在の店・猫・資金・他の目標を維持します。\n\n開始費用なし。開始後の取消・やり直しはできません。"},new PythonStartObjective{choice="bond",label="猫との好感度目標",can_start=true,details="好感度80以上の在籍猫を同時に6匹。期限なし。"},new PythonStartObjective{choice="patron",label="有力者の満足度目標",reason="開始済みです。",started=true,details="有力者：満足度0 / 100\n開始日：1日目"}}};
            Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(client,new object[]{state});apply();var p=preview.GetComponent<PythonObjectiveStartPanel>();var list=preview.GetComponent<PythonEventListPanel>();list.Open();if(list.entries.Length!=22 || !list.entries[21].interactable)throw new Exception("Objective entry missing");list.ObjectiveStart();if(list.panel.activeSelf || !p.panel.activeSelf || !p.proceed.interactable || !p.details.text.Contains("650"))throw new Exception("Objective display failed");Capture(preview,"Logs/ObjectiveStart.png");
            p.proceed.onClick.Invoke();if(!p.confirmation.activeSelf || !p.confirmationText.text.Contains("25日間") || !p.confirmationText.text.Contains("取消"))throw new Exception("Conditions confirmation failed");Capture(preview,"Logs/ObjectiveStartConfirmation.png");p.cancel.onClick.Invoke();if(typeof(PythonStateClient).GetField("pending",f).GetValue(client)!=null)throw new Exception("Cancel sent start");
            p.Choose();state.revision++;apply();if(p.confirmation.activeSelf)throw new Exception("Stale confirmation retained");p.tabs[2].onClick.Invoke();if(p.proceed.interactable || !p.details.text.Contains("開始済み"))throw new Exception("Started objective gate failed");p.tabs[1].onClick.Invoke();state.revision++;apply();if(!p.details.text.Contains("好感度80"))throw new Exception("Selection lost");p.Choose();p.Disconnect();if(p.confirmation.activeSelf || p.proceed.interactable || p.tabs[0].interactable)throw new Exception("Offline gate failed");apply();
            state.objective_start.rows[1].details=new string('長',4000);apply();Canvas.ForceUpdateCanvases();var scroll=p.details.transform.parent.parent.GetComponent<ScrollRect>();if(scroll.content.rect.height<=scroll.viewport.rect.height)throw new Exception("Details did not scroll");p.Choose();Canvas.ForceUpdateCanvases();var cs=p.confirmationText.GetComponentInParent<ScrollRect>();if(cs.content.rect.height<=cs.viewport.rect.height)throw new Exception("Confirmation did not scroll");p.Cancel();
            state.instance_id="loaded";apply();if(p.panel.activeSelf)throw new Exception("Load kept objective screen");p.Open();if(!p.details.text.Contains("650"))throw new Exception("Load did not reset selection");p.Choose();p.Confirm();var command=(PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client);if(command==null || command.kind!="start_objective" || command.choice!="popularity" || command.working_cats.Length!=0)throw new Exception("Start command incorrect");var id=command.request_id;p.Confirm();if(((PythonShiftCommand)typeof(PythonStateClient).GetField("pending",f).GetValue(client)).request_id!=id || p.proceed.interactable)throw new Exception("Duplicate start queued");Debug.Log("CAT_CAFE_OBJECTIVE_START_DISPLAY_OK");
        }
        static void Capture(ContentPreview preview,string path){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{preview,path});}
    }
}
